def G(t):
    R=[("sparse-checkout","спарс чекаут"),("commit-graph","коміт граф"),("README","рідмі"),("Scalar","Скейлер"),("scalar clone","скейлер клон"),("scalar","скейлер"),("open-source","опен сорс"),("github.com/git/git","гітхаб git слеш git"),("GitHub","Гітхаб"),("GitLab","Гітлаб"),("git clone","гіт клон"),("git blame","гіт блейм"),("git log","гіт лог"),("blame","блейм"),("Git","Гіт"),("git","гіт"),
       ("scion-daemon","Сайон демон"),("scion-cache","Сайон кеш"),("scion-server","Сайон сервер"),("Scion","Сайон"),("scn","ес-сі-ен"),
       ("Spanner","Спаннер"),("Piper","Пайпер"),("Sapling","Сеплінг"),("Meta","Мета"),("Google","Гугл"),("Anthropic","Антропік"),("Claude Code","Клод Код"),("Claude","Клод"),
       ("CI","сі-ай"),("CPU","процесора"),("checkout-ів","чекаутів"),("checkout","чекаут"),("depth 1","депс один"),("--filter=blob:none","фільтр блоб нан"),("--sparse","спарс"),("shallow","шеллоу"),("partial","паршл"),("sparse","спарс"),
       ("changeset","ченджсет"),("Antique","Антік"),("Linux","Лінукс"),("ГБ","гігабайт"),("МБ","мегабайт"),("ПБ","петабайт"),("RPC","ер-пі-сі")]
    for a,b in R: t=t.replace(a,b)
    t=re.sub(r"ШІ-(\w+)", r"\1 штучного інтелекту", t)
    return t.replace("ШІкарно","Шікарно").replace("ШІ","штучний інтелект")

